import ast,hashlib,importlib.util,json,pathlib
p=pathlib.Path('/workspace')
r=json.loads((p/'runtime_view.json').read_text())
q=json.loads((p/'proposal.json').read_text())

def validate(value,schema,path='study'):
 typ=schema.get('type')
 types={'object':dict,'array':list,'string':str,'boolean':bool,'integer':int}
 if typ: assert isinstance(value,types[typ]),(path,typ)
 if 'const' in schema: assert value==schema['const'],path
 if 'enum' in schema: assert value in schema['enum'],path
 if isinstance(value,str): assert len(value)>=schema.get('minLength',0),path
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),path
  for i,v in enumerate(value):validate(v,schema.get('items',{}),f'{path}[{i}]')
 if isinstance(value,dict):
  assert set(schema.get('required',[]))<=value.keys(),path
  props=schema.get('properties',{})
  if schema.get('additionalProperties') is False:assert value.keys()<=props.keys(),(path,value.keys()-props.keys())
  for k,v in value.items():
   if k in props:validate(v,props[k],path+'.'+k)
validate(q['study'],r['study_schema'])
assert q['study']['protocol_ref']==r['required_study_protocol_ref']
allowed=set(r['context']['allowed_observation_ids'])
assert set(q['study']['evidence_refs'])<=allowed
assert q['parent_trial'] in allowed
assert 1<=len(q['variants'])<=4
assert len(set(v['name'] for v in q['variants']))==len(q['variants'])
assert len(set(v['file'] for v in q['variants']))==len(q['variants'])
assert any(v['role']=='candidate' for v in q['variants'])

ancestor=ast.parse((p/'history_g1_r0037_match_observed_stop_task.py').read_text())
ancestor_class=next(n for n in ancestor.body if isinstance(n,ast.ClassDef))
def canonical_method(node):
 node=ast.parse(ast.unparse(node)).body[0]
 if isinstance(node.body[0],ast.Expr) and isinstance(node.body[0].value,ast.Constant) and isinstance(node.body[0].value.value,str):node.body.pop(0)
 if node.name=='__init__':
  for arg,default in zip(node.args.args[-len(node.args.defaults):],node.args.defaults):
   if arg.arg in ['summary_rotation_group','residual_routing']:default.value='SELECTOR'
 return ast.dump(node,include_attributes=False)
old_methods={n.name:canonical_method(n) for n in ancestor_class.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
for v in q['variants']:
 f=p/v['file']
 assert f.name==v['file'] and f.suffix=='.py' and f.is_file()
 s=f.read_text();compile(s,v['file'],'exec');t=ast.parse(s)
 c=next(ast.literal_eval(n.value) for n in t.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))
 assert c==v['config']
 cls=next(n for n in t.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 methods={n.name:canonical_method(n) for n in cls.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
 assert methods==old_methods, [name for name in methods if methods[name]"'!=old_methods.get(name)]
 init=next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name=='"'__init__')
 defaults={arg.arg:ast.literal_eval(default) for arg,default in zip(init.args.args[-len(init.args.defaults):],init.args.defaults)}
 for k,value in c.items():
  expected=defaults[k]
  if isinstance(expected,tuple) and isinstance(value,list):expected=list(expected)
  assert expected==value,(v['name'],k,expected,value)
 for n in ast.walk(t):
  if isinstance(n,ast.Import):assert all(a.name.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'} for a in n.names)
  if isinstance(n,ast.ImportFrom):assert n.module.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'open','eval','exec','compile','__import__'}
 sha=hashlib.sha256(s.encode()).hexdigest();assert sha in v['note']
 print(v['name'],'syntax/config/default/ancestor methods/imports/hash PASS',sha)
print('Study schema, protocol, evidence IDs, parent, variant roles/files and knowledge assessments PASS')
print('Identical inherited methods:',len(old_methods),'including constructor modulo two existing selector defaults')
print('No torch, training, scoring, tensor diagnostics or installation executed')
PY"

